<body>
  <!-- 状态栏主容器 -->
  <details class="status-main">
    <summary class="status-title">
      <i class="fa-solid fa-scroll"></i>
      <span>太宗文皇帝起居注</span>
    </summary>

    <div class="status-content-level1">
      <!-- 时间字段 -->
      <div class="status-field">
        <div class="field-label">
          <i class="fa-solid fa-clock"></i> 时间
        </div>
        <div class="field-value" data-field="time"></div>
      </div>

      <!-- 地点字段 -->
      <div class="status-field">
        <div class="field-label">
          <i class="fa-solid fa-location-dot"></i> 地点
        </div>
        <div class="field-value" data-field="location"></div>
      </div>

      <!-- 角色容器（动态生成） -->
      <div id="characters-container"></div>
    </div>
  </details>

  <!-- JavaScript 逻辑 -->
  <script type="module">
    // 限制角色数量（最少1个，最多4个）
    function limitCharacters(characters) {
      if (characters.length === 0) {
        return [{
          name: '未知角色',
          age: '未知',
          posture: '未知',
          clothing: '未知',
          thought: '未知'
        }];
      }

      // 按优先级和对话数量排序
      const sorted = characters.sort((a, b) => {
        const priorityA = a.priority ?? 0;
        const priorityB = b.priority ?? 0;
        if (priorityA !== priorityB) {
          return priorityB - priorityA;
        }
        const dialogueA = a.dialogueCount ?? 0;
        const dialogueB = b.dialogueCount ?? 0;
        return dialogueB - dialogueA;
      });

      return sorted.slice(0, 4);
    }

    // 创建角色卡片HTML
    function createCharacterCard(character, index) {
      return `
        <details class="status-character-details" data-character-index="${index}">
          <summary class="status-field-summary">
            <div class="status-field">
              <div class="field-label">
                <i class="fa-solid fa-user"></i> 角色名
              </div>
              <div class="field-value">${character.name}</div>
            </div>
          </summary>
          <div class="status-content-level2">
            <div class="status-field">
              <div class="field-label">
                <i class="fa-solid fa-calendar"></i> 年龄
              </div>
              <div class="field-value">${character.age}</div>
            </div>
            <div class="status-field">
              <div class="field-label">
                <i class="fa-solid fa-street-view"></i> 姿势表情
              </div>
              <div class="field-value">${character.posture}</div>
            </div>
            <div class="status-field">
              <div class="field-label">
                <i class="fa-solid fa-shirt"></i> 衣着
              </div>
              <div class="field-value">${character.clothing}</div>
            </div>
            <div class="status-field">
              <div class="field-label">
                <i class="fa-solid fa-brain"></i> 内心想法
              </div>
              <div class="field-value">${character.thought}</div>
            </div>
          </div>
        </details>
      `;
    }

    // 从消息文本中解析状态栏数据
    function parseFromMessageText() {
      try {
        const messageId = getIframeName().match(/\d+/)?.[0];
        if (!messageId) return null;

        // 获取当前消息内容
        const messages = getChatMessages(parseInt(messageId));
        if (messages.length === 0) return null;

        const text = messages[0].message || '';

        // 正则表达式匹配状态栏格式
        const regex = /<-ENVIRONMENT_DATA->[\r\n]*\|([^|]+)\|([^|]+)\|([^|]+)\|([^|]+)\|[\r\n]*<-CHARACTER_STATUS->[\r\n]*\|([^|]+)\|([^|]+)\|([^|]+)\|([^|]+)\|[\r\n]*/;
        const match = text.match(regex);

        if (!match) return null;

        const time = match[2].trim();
        const location = match[3].trim();
        const namesStr = match[4].trim();
        const agesStr = match[5].trim();
        const posturesStr = match[6].trim();
        const clothingStr = match[7].trim();
        const thoughtsStr = match[8].trim();

        // 解析角色名（用 / 分隔）
        const names = namesStr.split('/').map(n => n.trim());

        // 解析年龄（用 / 分隔）
        const ages = agesStr.split('/').map(a => a.trim());

        // 解析姿势表情（格式：角色名：内容/角色名：内容）
        const postures = {};
        posturesStr.split('/').forEach(item => {
          const colonIndex = item.indexOf('：');
          if (colonIndex > 0) {
            const name = item.substring(0, colonIndex).trim();
            const value = item.substring(colonIndex + 1).trim();
            postures[name] = value;
          }
        });

        // 解析衣着（格式：角色名：内容/角色名：内容）
        const clothing = {};
        clothingStr.split('/').forEach(item => {
          const colonIndex = item.indexOf('：');
          if (colonIndex > 0) {
            const name = item.substring(0, colonIndex).trim();
            const value = item.substring(colonIndex + 1).trim();
            clothing[name] = value;
          }
        });

        // 解析内心想法（格式：角色名：内容/角色名：内容）
        const thoughts = {};
        thoughtsStr.split('/').forEach(item => {
          const colonIndex = item.indexOf('：');
          if (colonIndex > 0) {
            const name = item.substring(0, colonIndex).trim();
            const value = item.substring(colonIndex + 1).trim();
            thoughts[name] = value;
          }
        });

        // 组装角色数据
        const characters = names.map((name, index) => ({
          name: name,
          age: ages[index] || '未知',
          posture: postures[name] || '未知',
          clothing: clothing[name] || '未知',
          thought: thoughts[name] || '未知'
        }));

        return {
          time: time,
          location: location,
          characters: limitCharacters(characters)
        };
      } catch (error) {
        console.error('从消息文本解析失败:', error);
        return null;
      }
    }

    // 从消息楼层变量中解析状态栏数据
    function parseFromVariables() {
      try {
        const messageId = getIframeName().match(/\d+/)?.[0];
        if (!messageId) return null;

        const variables = getVariables({
          type: 'message',
          message_id: parseInt(messageId)
        });

        const data = {
          time: variables.time || '未知',
          location: variables.location || '未知',
          characters: []
        };

        if (variables.characters && Array.isArray(variables.characters)) {
          data.characters = limitCharacters(variables.characters);
        } else if (variables.character) {
          data.characters = [{
            name: variables.character || '未知',
            age: variables.age || '未知',
            posture: variables.posture || '未知',
            clothing: variables.clothing || '未知',
            thought: variables.thought || '未知'
          }];
        } else {
          data.characters = limitCharacters([]);
        }

        return data;
      } catch (error) {
        console.error('从变量解析失败:', error);
        return null;
      }
    }

    // 解析状态栏数据（优先从消息文本，其次从变量）
    function parseStatusData() {
      // 优先尝试从消息文本解析
      let data = parseFromMessageText();

      // 如果消息文本解析失败，尝试从变量解析
      if (!data) {
        data = parseFromVariables();
      }

      // 如果都失败，返回默认数据
      if (!data) {
        data = {
          time: '未知',
          location: '未知',
          characters: limitCharacters([])
        };
      }

      return data;
    }

    // 更新界面显示
    function updateDisplay(data) {
      $('[data-field="time"]').text(data.time);
      $('[data-field="location"]').text(data.location);

      const container = $('#characters-container');
      container.empty();

      data.characters.forEach((character, index) => {
        container.append(createCharacterCard(character, index));
      });

      initCharacterAnimations();
    }

    // 初始化角色卡片动画
    function initCharacterAnimations() {
      $('.status-character-details').each(function() {
        const characterDetails = this;
        $(characterDetails).off('click toggle');

        characterDetails.addEventListener('click', (event) => {
          if (event.target.closest('.status-field-summary')) {
            event.stopPropagation();
          }
        });

        if (typeof gsap !== 'undefined') {
          characterDetails.addEventListener('toggle', () => {
            if (characterDetails.open) {
              const level2 = $(characterDetails).find('.status-content-level2 > .status-field');
              gsap.from(level2, {
                opacity: 0,
                x: -20,
                duration: 0.4,
                stagger: 0.08,
                ease: 'power2.out'
              });
            }
          });
        }
      });
    }

    // 初始化主容器动画
    function initMainAnimation() {
      const mainDetails = $('.status-main')[0];
      if (mainDetails && typeof gsap !== 'undefined') {
        mainDetails.addEventListener('toggle', () => {
          if (mainDetails.open) {
            gsap.from('.status-content-level1 > .status-field, .status-content-level1 .status-character-details', {
              opacity: 0,
              y: 15,
              duration: 0.4,
              stagger: 0.08,
              ease: 'power2.out'
            });
          }
        });
      }
    }

    // 加载时执行
    $(() => {
      console.log('状态栏界面已加载');

      const data = parseStatusData();
      if (data) {
        updateDisplay(data);
      }

      initMainAnimation();
    });

    // 卸载时执行
    $(window).on('pagehide', () => {
      console.log('状态栏界面已卸载');
    });
  </script>
</body>
</html>
